    features = create_features_for_time(t, cohort_users)

    # Match by stable anonymized GitHub ID, preserving test_input order.
    test_features = test_input.merge(
        features, left_on="UserID", right_on="github_user_id",
        how="left", sort=False, validate="one_to_one"
    )

    missing_users = test_features["user_id"].isna()
    print("Official users missing from processed Users:", int(missing_users.sum()))

    test_features = test_features.loc[~missing_users].copy().reset_index(drop=True)

    test_features["user_id"] = test_features["user_id"].astype("int64")

    test_features["prediction_time"] = t

    for col in target_cols:
        test_features[col] = 0  # loader compatibility only; not true labels

    # All historical features must be present; missing recencies use sentinel 999.
    assert test_features[feature_cols].notna().all().all()
    return test_features

