"""## Q1 — Schema graph: 8 tables, 20 PK→FK relationships, and dataset coverage

This diagram shows each of the **eight tables**, their **primary key** (blue), every **foreign key** (red), and arrows from each FK to its referenced PK. Edge direction is *child table → referenced parent table*, as required. The notebook's GNN internally adds reverse edges separately. A schema graph (8 table nodes) is not the same as the entity graph (one node per row).
"""

output_dir = Path("/content/report_figures")
output_dir.mkdir(parents=True, exist_ok=True)

def save_report_figure(graph, filename):
    """Export both SVG (sharp for slides/PDF) and PNG, then show SVG."""
    for fmt in ("svg", "png"):
        graph.render(filename=filename, directory=str(output_dir), format=fmt, cleanup=True)
    display(SVG(filename=str(output_dir / f"{filename}.svg")))

# Validate the diagram
assert len(TABLE_SPECS) == 8
assert len(FK_RELATIONS) == 20

# Step 12 — Q1: Database Schema Graph
# Reuse TABLE_SPECS and FK_RELATIONS from Step 6.

def make_q1_schema():

  # Display names only, not a second schema definition
  display_names = {
      "users": "Users",
      "repos": "Repositories",
      "prs": "PullRequests",
      "issues": "Issues",
      "issue_comments": "IssueComments",
      "reviews": "PRReviews",
      "review_comments": "PRReviewComments",
      "pushes": "Pushes",
  }

  schema = Digraph(
      "schema",
      graph_attr={
          "rankdir": "LR",
          "splines": "polyline",
          "pad": "0.35",
          "nodesep": "0.65",
          "ranksep": "1.6",
          "overlap": "false",
          "outputorder": "edgesfirst",
          "bgcolor": "white",
      },
      node_attr={
          "shape": "plain",
          "fontname": "Helvetica",
      },
      edge_attr={
          "color": "#7890A8",
          "penwidth": "0.85",
          "arrowsize": "0.6",
      }
  )

  # 1. Generate nodes from existing TABLE_SPECS
  for table_name, (pk, time_col) in TABLE_SPECS.items():

      rows = [
          f'<TR><TD BGCOLOR="#17324F" ALIGN="LEFT">'
          f'<FONT COLOR="white"><B>{display_names[table_name]}</B></FONT>'
          f'</TD></TR>',

          f'<TR><TD PORT="{pk}" ALIGN="LEFT" BGCOLOR="#DCEFE3">'
          f'<FONT COLOR="#124B2F"><B>PK  {pk}</B></FONT>'
          f'</TD></TR>',
      ]

      # Get foreign keys from existing FK_RELATIONS
      for child, fk, parent, known_at in FK_RELATIONS:

          if child != table_name:
              continue

          suffix = " (later-known)" if known_at else ""

          rows.append(
              f'<TR><TD PORT="{fk}" ALIGN="LEFT" BGCOLOR="#EEF4FA">'
              f'<FONT COLOR="#143F6B">FK  {fk}{suffix}</FONT>'
              f'</TD></TR>'
          )

      # Show row availability timestamp
      rows.append(
          f'<TR><TD ALIGN="LEFT" BGCOLOR="#F8FAFC">'
          f'<FONT COLOR="#67768A">row time: {time_col}</FONT>'
          f'</TD></TR>'
      )

      label = (
          '<<TABLE BORDER="1" CELLBORDER="1" '
          'CELLSPACING="0" CELLPADDING="7" COLOR="#CBD5E1">'
          + "".join(rows)
          + '</TABLE>>'
      )

      schema.node(table_name, label=label)


  # 2. Generate FK -> PK edges from existing FK_RELATIONS
  for child, fk, parent, known_at in FK_RELATIONS:

      parent_pk = TABLE_SPECS[parent][0]

      schema.edge(
          f"{child}:{fk}:e",
          f"{parent}:{parent_pk}:w",
          constraint="false" if child == parent else "true"
      )

  # 3. Export PNG and SVG
  for fmt in ["png", "svg"]:
      schema.render(
          filename="q1_schema_graph",
          directory=str(output_dir),
          format=fmt,
          cleanup=True
      )

  save_report_figure(schema, "q1_schema_graph")



# Run to create Q1 figure
make_q1_schema()

