    g.node("prep", "Official preprocess.py\nAnonymize + create 8 relational tables", fillcolor="#F1F5F9")
    g.node("time", "Prediction cutoff t\nOnly observations available before t", fillcolor="#F0FDF4", color="#16A34A")
    g.node("graph", "Temporal heterogeneous graph\n8 node types, 20 FK + reverse edges", fillcolor="#EAF2FF", color="#2563EB")
    g.node("columns", "Basic node attributes +\nenhanced column & time encoders", fillcolor="#EAF2FF", color="#2563EB")
    g.node("sample", "Neighbor sampling +\n2-layer heterogeneous GraphSAGE", fillcolor="#EAF2FF", color="#2563EB")
    g.node("stats", "6 activity types\n7/30/90d counts + unique repos + recency", fillcolor="#E6F7F3", color="#0D9488")
    g.node("scale", "Log transform + train-fitted StandardScaler\nTemporal MLP", fillcolor="#E6F7F3", color="#0D9488")
    g.node("fusion", "Concatenate user embeddings\nFusion MLP → six logits", fillcolor="#F2EEFF", color="#8B5CF6")
